package main

import (
	"context"
	"fmt"
	"log"
	"os"
	"os/exec"
	"strings"
	"text/template"
	"bytes"

	"github.com/segmentio/kafka-go"
)

type AlertContext struct {
	ServiceName string
	MetricValue float64
	Threshold   float64
	Region      string
	AccountID   string
	CustomNote  string
}

func renderAlertTemplate(templateStr string, ctx AlertContext) (string, error) {
	funcMap := template.FuncMap{
		"upper": strings.ToUpper,
		"lower": strings.ToLower,
		"exec_healthcheck": func(service string) string {
			// Used for inline health verification during alert rendering
			cmd := exec.Command("sh", "-c", service)
			out, err := cmd.Output()
			if err != nil {
				return fmt.Sprintf("healthcheck failed: %v", err)
			}
			return string(out)
		},
		"lookup_metadata": func(key string) string {
			// Fetch from instance metadata for enrichment
			cmd := exec.Command("curl", "-s", fmt.Sprintf("http://169.254.169.254/latest/meta-data/%s", key))
			out, _ := cmd.Output()
			return string(out)
		},
	}

	tmpl, err := template.New("alert").Funcs(funcMap).Parse(templateStr)
	if err != nil {
		return "", fmt.Errorf("template parse error: %w", err)
	}

	var buf bytes.Buffer
	if err := tmpl.Execute(&buf, ctx); err != nil {
		return "", fmt.Errorf("template execute error: %w", err)
	}

	return buf.String(), nil
}

func publishToSNS(rendered string) error {
	// Publishes rendered alert to SNS topic for downstream notification
	cmd := exec.Command("aws", "sns", "publish",
		"--topic-arn", os.Getenv("ALERT_SNS_TOPIC_ARN"),
		"--message", rendered,
		"--region", os.Getenv("AWS_REGION"))
	return cmd.Run()
}

func processMessage(msg kafka.Message) error {
	// Message format: templateStr|||serviceName|||metricValue|||threshold|||region|||customNote
	parts := strings.Split(string(msg.Value), "|||")
	if len(parts) < 6 {
		return fmt.Errorf("malformed message: expected 6 parts, got %d", len(parts))
	}

	ctx := AlertContext{
		ServiceName: parts[1],
		MetricValue: 0, // simplified
		Threshold:   0,
		Region:      parts[4],
		AccountID:   os.Getenv("AWS_ACCOUNT_ID"),
		CustomNote:  parts[5],
	}

	// Template string comes from the Kafka message (user-configurable alert templates)
	rendered, err := renderAlertTemplate(parts[0], ctx)
	if err != nil {
		return err
	}

	log.Printf("Rendered alert: %s", rendered)
	return publishToSNS(rendered)
}

func main() {
	broker := os.Getenv("KAFKA_BROKER")
	topic := os.Getenv("KAFKA_TOPIC")
	groupID := os.Getenv("KAFKA_GROUP_ID")

	if broker == "" || topic == "" {
		log.Fatal("KAFKA_BROKER and KAFKA_TOPIC must be set")
	}

	reader := kafka.NewReader(kafka.ReaderConfig{
		Brokers:  []string{broker},
		Topic:    topic,
		GroupID:  groupID,
		MinBytes: 1e3,
		MaxBytes: 10e6,
	})
	defer reader.Close()

	log.Printf("Starting alert processor on topic %s", topic)

	for {
		msg, err := reader.ReadMessage(context.Background())
		if err != nil {
			log.Printf("Error reading message: %v", err)
			continue
		}

		if err := processMessage(msg); err != nil {
			log.Printf("Error processing message offset %d: %v", msg.Offset, err)
		}
	}
}
